{"cmd":"cat > voauto/voauto.go <<'EOF'
package voauto

import (
	"fmt"
	"reflect"
	"strings"
	"sync"

	"github.com/take0fit/validationcontext"
)

type ConstructorFunc func(v any, vc *validationcontext.ValidationContext) any

var (
	constructors = make(map[string]ConstructorFunc)
	mu           sync.RWMutex
)

// Register registers a constructor function with a given key.
func Register(key string, constructor ConstructorFunc) {
	mu.Lock()
	defer mu.Unlock()
	constructors[key] = constructor
}

// GetConstructor retrieves a constructor function by key.
func GetConstructor(key string) ConstructorFunc {
	mu.RLock()
	defer mu.RUnlock()
	return constructors[key]
}

// BindAndValidate binds source data to a target struct and validates it.
func BindAndValidate[T any](source any) (*T, error) {
	vc := validationcontext.NewValidationContext()

	sourceValue, err := normalizeSourceValue(source)
	if err != nil {
		return nil, err
	}

	var result T
	resultValue := reflect.ValueOf(&result).Elem()
	resultType := reflect.TypeOf(result)
	if resultType.Kind() != reflect.Struct {
		return nil, fmt.Errorf("target type must be struct: %s", resultType.Kind())
	}

	for i := 0; i < resultType.NumField(); i++ {
		field := resultType.Field(i)
		constructorKey, sourceFieldName, parseErr := resolveBindingRule(field)
		if parseErr != nil {
			return nil, parseErr
		}

		sourceField := sourceValue.FieldByName(sourceFieldName)
		if !sourceField.IsValid() {
			return nil, fmt.Errorf("source field not found: %s", sourceFieldName)
		}

		constructor := GetConstructor(constructorKey)
		if constructor == nil {
			return nil, fmt.Errorf("constructor not found: %s", constructorKey)
		}

		resultObj, callErr := callConstructor(constructor, sourceField.Interface(), vc, constructorKey)
		if callErr != nil {
			return nil, callErr
		}
		if resultObj == nil {
			continue
		}

		resultFieldValue := resultValue.Field(i)
		if !resultFieldValue.CanSet() {
			return nil, fmt.Errorf("target field cannot be set: %s", field.Name)
		}

		resultObjValue := reflect.ValueOf(resultObj)
		if resultObjValue.Type().AssignableTo(resultFieldValue.Type()) {
			resultFieldValue.Set(resultObjValue)
			continue
		}
		if resultObjValue.Type().ConvertibleTo(resultFieldValue.Type()) {
			resultFieldValue.Set(resultObjValue.Convert(resultFieldValue.Type()))
			continue
		}
		return nil, fmt.Errorf("constructor result type mismatch for field %s: got %s, want %s", field.Name, resultObjValue.Type(), resultFieldValue.Type())
	}

	if vc.HasErrors() {
		return nil, vc.AggregateError()
	}

	return &result, nil
}

func normalizeSourceValue(source any) (reflect.Value, error) {
	if source == nil {
		return reflect.Value{}, fmt.Errorf("source must not be nil")
	}

	sourceValue := reflect.ValueOf(source)
	if sourceValue.Kind() == reflect.Ptr {
		if sourceValue.IsNil() {
			return reflect.Value{}, fmt.Errorf("source pointer must not be nil")
		}
		sourceValue = sourceValue.Elem()
	}
	if sourceValue.Kind() != reflect.Struct {
		return reflect.Value{}, fmt.Errorf("source must be a struct or pointer to struct: %s", sourceValue.Kind())
	}
	return sourceValue, nil
}

func resolveBindingRule(field reflect.StructField) (constructorKey, sourceFieldName string, err error) {
	tag := strings.TrimSpace(field.Tag.Get("vctag"))
	if tag == "" {
		return "New" + field.Name, field.Name, nil
	}

	constructorKey, sourceFieldName = parseTag(tag, field)
	if constructorKey == "" {
		return "", "", fmt.Errorf("invalid vctag for field %s: constructor key is empty", field.Name)
	}
	if sourceFieldName == "" {
		return "", "", fmt.Errorf("invalid vctag for field %s: source field is empty", field.Name)
	}
	if strings.HasPrefix(tag, "auto:") {
		constructorKey = generateKeyFromType(field.Type, constructorKey)
	}
	return constructorKey, sourceFieldName, nil
}

func callConstructor(constructor ConstructorFunc, input any, vc *validationcontext.ValidationContext, constructorKey string) (result any, err error) {
	defer func() {
		if recovered := recover(); recovered != nil {
			err = fmt.Errorf("constructor panic: %s: %v", constructorKey, recovered)
		}
	}()
	result = constructor(input, vc)
	return result, nil
}

func parseTag(tag string, field reflect.StructField) (constructorKey, sourceFieldName string) {
	cleanTag := strings.TrimPrefix(tag, "auto:")

	parts := strings.Split(cleanTag, ",")
	constructorKey = strings.TrimSpace(parts[0])

	if len(parts) > 1 {
		sourceFieldName = strings.TrimSpace(parts[1])
	} else {
		sourceFieldName = field.Name
	}

	return constructorKey, sourceFieldName
}

func generateKeyFromType(fieldType reflect.Type, constructorName string) string {
	pkgPath := fieldType.PkgPath()
	if pkgPath == "" {
		return constructorName
	}

	parts := strings.Split(pkgPath, "/")
	var keyParts []string

	if len(parts) >= 3 {
		keyParts = parts[len(parts)-3:]
	} else if len(parts) >= 2 {
		keyParts = parts[len(parts)-2:]
	} else {
		keyParts = []string{parts[len(parts)-1]}
	}

	packageKey := strings.Join(keyParts, "_")
	return packageKey + "_" + constructorName
}
EOF"}

{"cmd":"cat > internal/generator/generator.go <<'EOF'
package generator

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Generator handles the code generation process
type Generator struct {
	verbose         bool
	explicitPkgPath string
	packageDataMap  map[string]*PackageData
}

// New creates a new Generator instance
func New(verbose bool, explicitPkgPath string) *Generator {
	return &Generator{
		verbose:         verbose,
		explicitPkgPath: explicitPkgPath,
		packageDataMap:  make(map[string]*PackageData),
	}
}

// ScanDirectory scans a directory for Go files and collects generation data.
func (g *Generator) ScanDirectory(targetDir string) (int, int, error) {
	files := make([]string, 0)
	err := filepath.WalkDir(targetDir, func(path string, d fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if d.IsDir() {
			if isIgnoredDir(d.Name()) {
				return filepath.SkipDir
			}
			return nil
		}
		if isTargetGoFile(path) {
			files = append(files, path)
		}
		return nil
	})
	if err != nil {
		return 0, 0, err
	}

	sort.Strings(files)

	fileCount := 0
	generateCommentCount := 0
	for _, path := range files {
		fileCount++
		if g.verbose {
			fmt.Printf("Processing file: %s\n", path)
		}
		commentCount := g.processFile(path)
		generateCommentCount += commentCount
	}

	return fileCount, generateCommentCount, nil
}

func isIgnoredDir(name string) bool {
	switch name {
	case ".git", "vendor":
		return true
	default:
		return false
	}
}

func isTargetGoFile(path string) bool {
	if !strings.HasSuffix(path, ".go") {
		return false
	}
	if strings.HasSuffix(path, "_test.go") {
		return false
	}
	if strings.HasSuffix(path, "registry_init.go") {
		return false
	}
	return true
}

// GenerateRegistries generates registry files for all collected packages.
func (g *Generator) GenerateRegistries() (int, error) {
	count := 0
	for packageDir, data := range g.packageDataMap {
		if len(data.Registrations) > 0 {
			if err := g.generateRegistryForPackage(data, packageDir); err != nil {
				return count, err
			}
			count++
		}
	}
	return count, nil
}

var _ = os.FileInfo(nil)
EOF"}

{"cmd":"cat > internal/generator/parser.go <<'EOF'
package generator

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"log"
	"path/filepath"
	"regexp"
	"strings"
)

var generateCommentRegexp = regexp.MustCompile(`//go:generate\s+(?:voauto-gen|validationcontext)(?:\s+(.+))?`)

// processFile processes a single Go file and collects registration data.
func (g *Generator) processFile(filename string) int {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, filename, nil, parser.ParseComments)
	if err != nil {
		log.Printf("failed to parse file %s: %v", filename, err)
		return 0
	}

	packageDir := filepath.Dir(filename)
	generateCommentCount := 0
	var config *GenerateConfig

	for _, commentGroup := range file.Comments {
		for _, comment := range commentGroup.List {
			if g.verbose {
				fmt.Printf("  Comment: %s\n", comment.Text)
			}

			parsedConfig, ok := parseGenerateComment(comment.Text)
			if !ok {
				continue
			}

			generateCommentCount++
			if g.verbose {
				fmt.Printf("Found generate comment in %s: %s\n", filename, comment.Text)
			}
			config = parsedConfig
			break
		}
		if config != nil {
			break
		}
	}

	if config != nil {
		g.ensurePackageData(packageDir, file, config)
		packageData := g.packageDataMap[packageDir]
		registrations := collectRegistrationsFromFile(file, config, packageData.PackagePath, g.verbose)
		packageData.Registrations = append(packageData.Registrations, registrations...)

		if g.verbose {
			fmt.Printf("  Added %d registrations from %s\n", len(registrations), filename)
		}
	}

	return generateCommentCount
}

// ensurePackageData ensures package data exists for the given directory.
func (g *Generator) ensurePackageData(packageDir string, file *ast.File, config *GenerateConfig) {
	if g.packageDataMap[packageDir] == nil {
		var packagePath string

		if g.explicitPkgPath != "" {
			if !strings.Contains(g.explicitPkgPath, "/") {
				currentPkgPath := getCurrentPackagePath()
				if currentPkgPath != "" {
					packagePath = currentPkgPath
					if g.verbose {
						fmt.Printf("  Using current directory package path: %s\n", packagePath)
					}
				} else {
					packagePath = g.explicitPkgPath
					if g.verbose {
						fmt.Printf("  Using GOPACKAGE: %s\n", packagePath)
					}
				}
			} else {
				packagePath = g.explicitPkgPath
				if g.verbose {
					fmt.Printf("  Using explicit package path: %s\n", packagePath)
				}
			}
		} else {
			moduleDir := findModuleRoot(packageDir)
			packagePath = getPackagePath(moduleDir, packageDir)
			if g.verbose {
				fmt.Printf("  Auto-detected package path: %s\n", packagePath)
			}
		}

		if g.verbose {
			fmt.Printf("  Package directory: %s\n", packageDir)
			fmt.Printf("  Final package path: %s\n", packagePath)
		}

		g.packageDataMap[packageDir] = &PackageData{
			PackageName:   file.Name.Name,
			PackagePath:   packagePath,
			Registrations: []Registration{},
			Config:        config,
		}
	}
}

// parseGenerateComment parses //go:generate comment and extracts configuration.
func parseGenerateComment(comment string) (*GenerateConfig, bool) {
	matches := generateCommentRegexp.FindStringSubmatch(comment)
	if len(matches) == 0 {
		return nil, false
	}

	args := ""
	if len(matches) > 1 {
		args = matches[1]
	}

	config := &GenerateConfig{
		OutputPath:    "registry_init.go",
		OutputPackage: "",
	}

	parts := strings.Fields(args)
	for _, part := range parts {
		switch {
		case strings.HasPrefix(part, "-output="):
			value := strings.TrimSpace(strings.TrimPrefix(part, "-output="))
			if value != "" {
				config.OutputPath = value
			}
		case strings.HasPrefix(part, "-package="):
			config.OutputPackage = strings.TrimSpace(strings.TrimPrefix(part, "-package="))
		case strings.HasPrefix(part, "-methods="):
			methodsStr := strings.TrimSpace(strings.TrimPrefix(part, "-methods="))
			if methodsStr == "" {
				continue
			}
			methods := strings.Split(methodsStr, ",")
			for _, method := range methods {
				trimmed := strings.TrimSpace(method)
				if trimmed != "" {
					config.Methods = append(config.Methods, trimmed)
				}
			}
		}
	}

	return config, true
}
EOF"}

